module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);
// Internal Registers
reg [3:0] data;
reg [1:0] cnt;
reg valid;
// Sequential Block
always @(posedge clk or posedge rst_n) begin
    if (rst_n) begin
        cnt <= 2'b0;
        valid <= 1'b0;
    end else begin
        if (cnt == 2'b11) begin
            data <= d;
            cnt <= 2'b0;
            valid <= 1'b1;
        end else begin
            cnt <= cnt + 1;
            valid <= 1'b0;
            data <= {data[2:0], data[3]};
        end
    end
end
// Combinational Assignment
always @(*) begin
    dout = data[3];
    valid_out = valid;
end
endmodule
